import sys; sys.path.insert(0,'.')
from lib import *
P,y,ids,X = load_data(practice, tokenize, LABELS)
V=30522; N=len(P)
n=np.array([len(t) for t in ids]); Xtf=sp.diags(1.0/n)@X
nrm=np.sqrt(np.asarray(X.multiply(X).sum(1)).ravel()); Xl2=sp.diags(1.0/nrm)@X
def nb(tr,alpha=0.3):
    cnt=np.zeros((V,8))
    for c in range(8): cnt[:,c]=np.asarray(X[tr][y[tr]==c].sum(0)).ravel()
    lp=np.log(cnt+alpha)-np.log(cnt.sum(0)+alpha*V); return lp-lp.mean(1,keepdims=True)
def ridge(tr,Xf,lam):
    Xc=Xf[tr]; Yc=np.eye(8)[y[tr]]
    Kk=(Xc@Xc.T).toarray(); A=np.linalg.solve(Kk+lam*np.eye(len(tr)), Yc-Yc.mean(0))
    S=np.asarray(Xc.T@A); return S-S.mean(1,keepdims=True)
res={}
for seed in [0,1,2]:
    rng=np.random.RandomState(seed); perm=rng.permutation(N); folds=np.array_split(perm,5)
    for f in folds:
        tr=np.setdiff1d(np.arange(N),f)
        T={'nb':nb(tr)}
        for lam in [1e-3,3e-3,1e-2]: T[f'rtf{lam}']=ridge(tr,Xtf,lam)
        for lam in [0.3,1,3]: T[f'rcnt{lam}']=ridge(tr,X,lam)
        for lam in [0.03,0.1,0.3]: T[f'rl2{lam}']=ridge(tr,Xl2,lam)
        T['blend']=T['nb']/4+T['rtf0.003']
        T['blend2']=T['nb']/8+T['rtf0.003']
        T['blend3']=T['nb']/2+T['rtf0.003']
        T['blend_l2']=T['nb']/4+T['rtf0.003']+ T['rl20.1']*np.linalg.norm(T['rtf0.003'])/np.linalg.norm(T['rl20.1'])
        for k,S in T.items():
            res.setdefault(k,[]).append(((X[f]@S).argmax(1)==y[f]).mean())
for k,v in res.items(): print(f'{k:12s} {np.mean(v):.4f}')
